    def test_pkcs12_extract_with_customcrypto_bde50(self):
        '''Check if customcrypto can decrypt BDE 5.0 pkcs12 (3DES/RC2)'''

        mock_p12_data_bytebooks = ""
        mock_p12_data_adobe = ""

        mock_p12_password = b"9jz9QR6xNQ4h/UjyjisAZg=="

        cert_bb, privkey_bb = self.__internal_pkcs12_extract_with_customcrypto(mock_p12_data_bytebooks, mock_p12_password)
        cert_adobe, privkey_adobe = self.__internal_pkcs12_extract_with_customcrypto(mock_p12_data_adobe, mock_p12_password)

        dummy_cert_data_bytebooks = base64.b64decode("")
        dummy_cert_data_adobe = base64.b64decode("")
        dummy_key_data = base64.b64decode("")

        self.assertEqual(cert_bb, dummy_cert_data_bytebooks, "p12 cert invalid after extraction (Bytebooks)")
        self.assertEqual(cert_adobe, dummy_cert_data_adobe, "p12 cert invalid after extraction (Adobe)")

        self.assertEqual(privkey_bb, dummy_key_data, "p12 key invalid after extraction (ByteBooks)")
        self.assertEqual(privkey_adobe, dummy_key_data, "p12 key invalid after extraction (Adobe)")
        self.assertEqual(privkey_adobe, privkey_bb, "p12 privkeys aren't identical")


    def test_pkcs12_extract_with_cryptography(self): 
        '''Check if cryptography (unused) can extract pkcs12'''

        # This uses cryptography.hazmat to extract the PKCS data. That's not what the plugin is using right now.

        mock_p12_data = ""
        mock_p12_password = base64.b64encode(b"1234")

        try: 
            from cryptography.hazmat.primitives.serialization import pkcs12
            from cryptography.hazmat.primitives.serialization import Encoding, PrivateFormat, NoEncryption
        except: 
            return self.skipTest("cryptography not installed")


        privkey, cert, _ = pkcs12.load_key_and_certificates(base64.b64decode(mock_p12_data), mock_p12_password)
        privkey = privkey.private_bytes(Encoding.DER, PrivateFormat.PKCS8, NoEncryption())
        cert = cert.public_bytes(Encoding.DER)

        # privkey now is in PKCS#8 format. That's a wrapper around the actual PKCS#1 key. 
        # See https://tls.mbed.org/kb/cryptography/asn1-key-structures-in-der-and-pem for details.
        # Throw away the PKCS#8 wrapper: 
        privkey = privkey[26:]

        # Verify result:
        dummy_cert_data = base64.b64decode("")
        dummy_key_data = base64.b64decode("")

        self.assertEqual(cert, dummy_cert_data, "p12 cert invalid after extraction")
        self.assertEqual(privkey, dummy_key_data, "p12 key invalid after extraction")
   

    def test_pkcs12_extract_plugin_implementation(self): 
        '''Check if the plugin is capable of extracting the pkcs12 certificate (AES/AES)'''

        mock_p12_data = ""
        # Actual key password is "1234" base64-encoded = "MTIzNA=="

        mock_p12_password = b"1234"

        libadobe.devkey_bytes = mock_p12_password
        try:
            decrypted = libadobeFulfill.getDecryptedCert(mock_p12_data)
        finally:
            libadobe.devkey_bytes = None

        # getDecryptedCert returns the certificate. The tests in test_adobe_requests.py
        # check that signing gets the key out of the pkcs12 correctly.
        dummy_cert_data = base64.b64decode("")

        self.assertEqual(decrypted, dummy_cert_data, "getDecryptedCert didn't return the certificate")

    

